from collections import deque

def main():
    r, c = map(int, input().split())
    g = [input() for _ in range(r)]
    for i in range(r):
        for j in range(c):
            if g[i][j] == "S":
                s = (i, j)
            if g[i][j] == "T":
                t = (i, j)
    dist = {s: 0}
    q = deque([s])
    while q:
        x, y = q.popleft()
        if (x, y) == t:
            print(dist[t])
            return
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < r and 0 <= ny < c and g[nx][ny] != "#" and (nx, ny) not in dist:
                dist[(nx, ny)] = dist[(x, y)] + 1
                q.append((nx, ny))
    print(-1)

def main():
    n, m = map(int, input().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)
    seen = [False] * (n + 1)
    cnt = 0
    for s in range(1, n + 1):
        if seen[s]:
            continue
        cnt += 1
        seen[s] = True
        st = [s]
        while st:
            x = st.pop()
            for y in adj[x]:
                if not seen[y]:
                    seen[y] = True
                    st.append(y)
    print(cnt)

